import type {
  DocumentAnalysisResponse,
  LanguageInsight,
} from "@inkflow/shared";
import { fallbackInsight } from "../data/demo";

export interface ExtractedDocument {
  name: string;
  kind: string;
  text: string;
  pages?: number;
  warnings: string[];
}

const plainTextExtensions = new Set([
  "txt",
  "md",
  "markdown",
  "html",
  "htm",
  "csv",
  "json",
  "xml",
  "srt",
  "vtt",
]);

const stopWords = new Set([
  "about",
  "after",
  "again",
  "against",
  "because",
  "before",
  "being",
  "between",
  "could",
  "every",
  "from",
  "have",
  "into",
  "more",
  "most",
  "other",
  "should",
  "some",
  "such",
  "than",
  "that",
  "their",
  "there",
  "these",
  "they",
  "this",
  "through",
  "under",
  "very",
  "what",
  "when",
  "where",
  "which",
  "while",
  "with",
  "would",
  "your",
]);

function extensionOf(name: string) {
  return name.split(".").pop()?.toLowerCase() ?? "";
}

function cleanText(text: string) {
  return text
    .replace(/\u0000/g, "")
    .replace(/\r/g, "\n")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
}

function htmlToText(source: string) {
  const parsed = new DOMParser().parseFromString(source, "text/html");
  parsed
    .querySelectorAll("script, style, noscript, svg, nav")
    .forEach((node) => node.remove());
  return cleanText(parsed.body.textContent ?? "");
}

async function extractPdf(file: File, warnings: string[]) {
  const pdfjs = await import("pdfjs-dist");
  const workerUrl = (
    await import("pdfjs-dist/build/pdf.worker.min.mjs?url")
  ).default;
  pdfjs.GlobalWorkerOptions.workerSrc = workerUrl;

  const bytes = new Uint8Array(await file.arrayBuffer());
  const pdf = await pdfjs.getDocument({
    data: bytes,
    useWorkerFetch: false,
  }).promise;
  const pages: string[] = [];

  for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber += 1) {
    const page = await pdf.getPage(pageNumber);
    const content = await page.getTextContent();
    const text = content.items
      .map((item) => ("str" in item ? item.str : ""))
      .join(" ");
    pages.push(text);
    page.cleanup();
  }

  const text = cleanText(pages.join("\n\n"));
  if (!text) {
    warnings.push("This PDF appears to be scanned. Import page images to use OCR.");
  }
  return { text, pages: pdf.numPages };
}

async function extractDocx(file: File) {
  const mammoth = await import("mammoth");
  const result = await mammoth.extractRawText({
    arrayBuffer: await file.arrayBuffer(),
  });
  return cleanText(result.value);
}

function slideNumber(path: string) {
  return Number(path.match(/slide(\d+)\.xml$/)?.[1] ?? 0);
}

async function extractPptx(file: File) {
  const JSZip = (await import("jszip")).default;
  const archive = await JSZip.loadAsync(await file.arrayBuffer());
  const slides = Object.keys(archive.files)
    .filter((path) => /^ppt\/slides\/slide\d+\.xml$/.test(path))
    .sort((left, right) => slideNumber(left) - slideNumber(right));
  const output: string[] = [];

  for (const path of slides) {
    const xml = await archive.file(path)?.async("text");
    if (!xml) continue;
    const parsed = new DOMParser().parseFromString(xml, "application/xml");
    const nodes = [...parsed.getElementsByTagNameNS("*", "t")];
    const text = nodes.map((node) => node.textContent ?? "").join(" ");
    if (text.trim()) output.push(`Slide ${slideNumber(path)}\n${text}`);
  }
  return cleanText(output.join("\n\n"));
}

async function extractEpub(file: File) {
  const JSZip = (await import("jszip")).default;
  const archive = await JSZip.loadAsync(await file.arrayBuffer());
  const contentFiles = Object.keys(archive.files)
    .filter((path) => /\.(xhtml|html|htm)$/i.test(path))
    .filter((path) => !/nav|toc|cover/i.test(path))
    .sort((left, right) => left.localeCompare(right, undefined, { numeric: true }));
  const sections: string[] = [];

  for (const path of contentFiles) {
    const source = await archive.file(path)?.async("text");
    if (source) {
      const text = htmlToText(source);
      if (text) sections.push(text);
    }
  }
  return cleanText(sections.join("\n\n"));
}

export async function extractDocument(file: File): Promise<ExtractedDocument> {
  const extension = extensionOf(file.name);
  const warnings: string[] = [];
  let text = "";
  let pages: number | undefined;

  if (extension === "pdf") {
    const result = await extractPdf(file, warnings);
    text = result.text;
    pages = result.pages;
  } else if (extension === "docx") {
    text = await extractDocx(file);
  } else if (extension === "pptx") {
    text = await extractPptx(file);
  } else if (extension === "epub") {
    text = await extractEpub(file);
  } else if (file.type.startsWith("text/") || plainTextExtensions.has(extension)) {
    const raw = await file.text();
    if (extension === "html" || extension === "htm" || extension === "xml") {
      text = htmlToText(raw);
    } else if (extension === "json") {
      try {
        text = JSON.stringify(JSON.parse(raw), null, 2);
      } catch {
        text = raw;
      }
    } else {
      text = cleanText(raw);
    }
  } else if (extension === "doc") {
    throw new Error("旧版 .doc 暂不支持，请在 Word 中另存为 .docx 后导入。");
  } else {
    throw new Error(`暂不支持 .${extension || "unknown"} 文档。`);
  }

  if (!text) {
    throw new Error("没有从这份文档中识别到可分析的文本。");
  }

  return {
    name: file.name,
    kind: extension.toUpperCase() || file.type || "DOCUMENT",
    text,
    pages,
    warnings,
  };
}

function documentSentences(text: string) {
  return (
    text
      .replace(/\s+/g, " ")
      .match(/[^.!?。！？]+[.!?。！？]?/g)
      ?.map((part) => part.trim()) ?? []
  ).filter((part) => part.length > 24);
}

function frequentEnglishTerms(text: string, limit = 8) {
  const words = text.toLowerCase().match(/[a-z][a-z'-]{3,}/g) ?? [];
  const frequencies = new Map<string, number>();
  for (const word of words) {
    if (stopWords.has(word)) continue;
    frequencies.set(word, (frequencies.get(word) ?? 0) + 1);
  }
  return [...frequencies.entries()]
    .sort((left, right) => right[1] - left[1])
    .map(([term]) => term)
    .slice(0, limit);
}

export function analyzeDocumentLocally(
  title: string,
  text: string,
): DocumentAnalysisResponse {
  const compact = cleanText(text).replace(/\s+/g, " ");
  const sentences = documentSentences(compact);
  const terms = frequentEnglishTerms(compact);
  const keyExpressions: LanguageInsight[] = terms.map((term) =>
    fallbackInsight(term),
  );
  const keyPoints = sentences.slice(0, 4).map((sentence, index) => ({
    heading: `要点 ${index + 1}`,
    explanationZh:
      index === 0
        ? "这是文档最先建立的核心信息，适合作为理解全文的起点。"
        : "这一段补充了主要论述，可结合上下文继续精读。",
    sourceQuote: sentence.slice(0, 240),
  }));

  return {
    title,
    summaryZh:
      sentences.slice(0, 3).join(" ") ||
      `文档围绕 ${terms.slice(0, 3).join("、") || "核心表达"} 展开。`,
    overviewZh:
      "先阅读摘要和要点，再把高价值表达逐个收入单词本，最后用翻卡与拼写复习。",
    keyPoints,
    keyExpressions,
    readingTimeMinutes: Math.max(
      1,
      Math.ceil((compact.match(/[a-z]+/gi)?.length ?? 0) / 220),
    ),
    provider: "mock",
    model: "local-fallback",
  };
}
